raw:
{
  "candidates": [
    {
      "claimType": "phaseState",
      "statement": "该用户当前处于婴儿养育的早期阶段（约0-6个月），且主要照护者正经历夜间睡眠碎片化的常态期。",
      "supportingRefs": [
        "o1",
        "o3",
        "o5"
      ],
      "alternativeExplanations": [
        "用户可能是在为早产儿或特殊需求婴儿进行长期护理，而非普通早期阶段",
        "夜间喂养频率低可能是由配方奶喂养效率较高或引入安抚物导致，而非单纯的生理常态"
      ],
      "verificationPlan": [
        {
          "op": "retrieveRelated",
          "question": "查询近3个月内是否有出生证明、满月/百天相关记录或母婴用品（如推车、安全座椅）的大额购买记录以确认婴儿月龄。"
        },
        {
          "op": "checkCoverage",
          "question": "检查白天时段的活动记录或购物记录，验证是否存在“补觉”相关的行为模式（如白天长时间离线、购买助眠产品等）。"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现婴儿已超6个月或存在严重睡眠障碍诊断，则命题从“早期常态”调整为“特殊护理期”或“问题干预期”。",
      "evidenceGrade": "支持",
      "action": "adopt"
    },
    {
      "claimType": "recurringBehavior",
      "statement": "该用户承担主要的婴儿日常物资采购与基础健康事务管理职责。",
      "supportingRefs": [
        "o2",
        "o4"
      ],
      "alternativeExplanations": [
        "用户可能仅负责特定品类（如尿不湿）的代购，而奶粉等其他物品由他人负责",
        "疫苗预约可能仅为一次性代办，不代表长期的健康管理责任"
      ],
      "verificationPlan": [
        {
          "op": "comparePeriods",
          "question": "对比过去6个月的采购记录，确认尿不湿/湿巾及奶粉的购买是否持续由同一账户/身份执行，排除偶发性代购。"
        },
        {
          "op": "searchCounterEvidence",
          "question": "查找是否有其他家庭成员（attribution为other）在同期进行的婴儿相关大额采购或任务记录，以评估责任分担情况。"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现主要物资采购分散在不同人员名下，则命题从“主要职责”调整为“部分协助”或“特定品类负责人”。",
      "evidenceGrade": "线索",
      "action": "ask"
    }
  ]
}
